//! Safrole ticket oracle: context extraction, emulated ring-VRF ticket
//! generation, verification, proxy assignment, and CE 131/132 scheduling.

use jam_node::hazmat::KeystoreSigner;
use jam_std_common::{
    bandersnatch::{self, ring_vrf},
    Entropy,
};

use crate::chain::{ChainError, RefChain};

/// Ticket context for a target epoch.
pub struct TicketCtx {
    /// Serialized bandersnatch public keys of the designated validators.
    pub pks: Vec<[u8; 32]>,
    /// Tickets entropy for the target epoch (entropy buffer entry 1).
    pub entropy: [u8; 32],
}

/// A ticket generated by an emulated validator.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct EmulatedTicket {
    /// Ring-VRF output (ticket id / score).
    pub id: [u8; 32],
    /// Emulated author index.
    pub author: usize,
    /// Ticket attempt.
    pub attempt: u8,
    /// Raw ring signature bytes (32 + 752).
    pub proof: [u8; 784],
    /// Proxy index over the validator set.
    pub proxy: usize,
}

/// How a ticket is delivered to the NUT.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TicketDelivery {
    /// Emulated author sends CE 131 to the NUT-as-proxy.
    Ce131,
    /// Emulated validator sends CE 132 to the NUT, standing in for the proxy forward.
    Ce132,
}

/// A ticket plus its scheduled delivery.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ScheduledTicket {
    pub ticket: EmulatedTicket,
    pub delivery: TicketDelivery,
    pub slot: u32,
    /// Epoch the ticket is *for*, which is not the epoch it is delivered in.
    pub target_epoch: u32,
}

impl RefChain {
    /// Ticket context for the current head state: serialized bandersnatch
    /// public keys of the designated validators and the tickets entropy
    /// (entropy buffer entry 1, current after the upcoming epoch change).
    pub fn ticket_ctx(&self) -> Result<TicketCtx, ChainError> {
        let storage = self.harness().storage(None);
        let validators = storage
            .designate_validators()
            .map_err(|e| ChainError::Tickets(format!("designate_validators: {e}")))?;
        let pks = validators.iter().map(|v| v.bandersnatch.0).collect();
        let entropy = storage
            .entropy()
            .map_err(|e| ChainError::Tickets(format!("entropy: {e}")))?[1]
            .0;
        Ok(TicketCtx { pks, entropy })
    }

    /// Generate tickets for every keystore-backed author (the emulated set,
    /// excluding the NUT), one per attempt up to `tickets_attempts_number()`.
    pub fn generate_tickets(&self, ctx: &TicketCtx) -> Result<Vec<EmulatedTicket>, ChainError> {
        let pks: Vec<bandersnatch::Public> =
            ctx.pks.iter().map(|p| bandersnatch::Public(*p)).collect();
        let keystore = self.harness().keystore();
        let mut tickets = Vec::new();
        for (author, pk) in pks.iter().enumerate() {
            if !keystore.has_bandersnatch(pk) {
                continue;
            }
            let prover = ring_vrf::RingContext::prover(&pks, author);
            for attempt in 0..jam_types::tickets_attempts_number() {
                let message = bandersnatch::Message::TicketSeal(Entropy(ctx.entropy), attempt);
                let signature = keystore
                    .bandersnatch_ring_sign(pk, &message, &[], &prover)
                    .map_err(|e| ChainError::Tickets(format!("ring sign author {author}: {e}")))?;
                let id = signature.vrf_output().0;
                tickets.push(EmulatedTicket {
                    id,
                    author,
                    attempt,
                    proof: signature.0,
                    proxy: proxy_index(&id, pks.len()),
                });
            }
        }
        Ok(tickets)
    }
}

/// Index of the validator designated as proxy for a ticket (polkajam rule:
/// big-endian last 4 bytes of the ticket id, modulo the validator count).
pub fn proxy_index(ticket_id: &[u8; 32], val_count: usize) -> usize {
    let last4 = &ticket_id[28..32];
    u32::from_be_bytes([last4[0], last4[1], last4[2], last4[3]]) as usize % val_count
}

/// First slot at which the emulator delivers tickets to the NUT.
///
/// Tickets are *for* the next epoch but must be *submitted* during the current
/// one, before its tail (`epoch_tail_start`); scheduling them at the next
/// epoch's start pushes delivery a whole epoch into the future, past any
/// realistic observation window.
pub fn first_delivery_slot(now_slot: u32) -> u32 {
    let period = jam_types::epoch_period();
    if now_slot % period < jam_types::epoch_tail_start() {
        now_slot + 1
    } else {
        (now_slot / period + 1) * period + 1
    }
}

/// Schedule delivery of each ticket within the epoch submission window.
///
/// A ticket whose proxy is the NUT goes via CE 131 at `epoch_start + 1`; any
/// other ticket is delivered via CE 132 at a deterministic slot in
/// `[epoch_start + 1, epoch_start + 5]` (round-robin by author index).
pub fn plan_tickets(
    tickets: &[EmulatedTicket],
    nut_index: usize,
    first_slot: u32,
    target_epoch: u32,
) -> Vec<ScheduledTicket> {
    tickets
        .iter()
        .map(|t| {
            if t.proxy == nut_index {
                ScheduledTicket {
                    ticket: t.clone(),
                    delivery: TicketDelivery::Ce131,
                    slot: first_slot,
                    target_epoch,
                }
            } else {
                ScheduledTicket {
                    ticket: t.clone(),
                    delivery: TicketDelivery::Ce132,
                    slot: first_slot + (t.author % 5) as u32,
                    target_epoch,
                }
            }
        })
        .collect()
}

/// Verify a ticket's ring signature against the context's validator ring.
pub fn verify_ticket(ctx: &TicketCtx, attempt: u8, proof: &[u8; 784]) -> bool {
    let pks: Vec<bandersnatch::Public> = ctx.pks.iter().map(|p| bandersnatch::Public(*p)).collect();
    let Ok(verifier) =
        ring_vrf::RingContext::verifier_from_commitment(ring_vrf::RingContext::commitment(&pks))
    else {
        return false;
    };
    let signature = ring_vrf::Signature(*proof);
    signature
        .ring_vrf_verify(
            &bandersnatch::Message::TicketSeal(Entropy(ctx.entropy), attempt),
            &[],
            &verifier,
        )
        .is_ok()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tickets_generate_and_verify() -> Result<(), ChainError> {
        let chain = RefChain::tiny(1..6)?;
        let ctx = chain.ticket_ctx()?;
        let tickets = chain.generate_tickets(&ctx)?;
        assert!(!tickets.is_empty(), "expected emulated tickets");
        assert_eq!(
            tickets.len(),
            5 * jam_types::tickets_attempts_number() as usize
        );
        for t in &tickets {
            assert!(
                verify_ticket(&ctx, t.attempt, &t.proof),
                "author {} attempt {} must verify",
                t.author,
                t.attempt
            );
        }
        Ok(())
    }

    #[test]
    fn ticket_wrong_attempt_fails_verify() -> Result<(), ChainError> {
        let chain = RefChain::tiny(1..6)?;
        let ctx = chain.ticket_ctx()?;
        let tickets = chain.generate_tickets(&ctx)?;
        let t = &tickets[0];
        let wrong = if t.attempt == 0 { 1 } else { 0 };
        assert!(!verify_ticket(&ctx, wrong, &t.proof));
        Ok(())
    }

    #[test]
    fn proxy_index_matches_polkajam() {
        for val_count in [3usize, 6, 10] {
            for last4 in [0x0000_0000u32, 0x0000_0001, 0xFFFF_FFFF, 0x1234_5678] {
                let mut id = [0u8; 32];
                id[28..32].copy_from_slice(&last4.to_be_bytes());
                assert_eq!(proxy_index(&id, val_count), (last4 as usize) % val_count);
            }
        }
    }

    #[test]
    fn plan_slots_within_window() -> Result<(), ChainError> {
        let chain = RefChain::tiny(1..6)?;
        let ctx = chain.ticket_ctx()?;
        let tickets = chain.generate_tickets(&ctx)?;
        let nut_index = 0;
        let first = 1001;
        let plan = plan_tickets(&tickets, nut_index, first, 42);
        assert!(!plan.is_empty());
        for s in &plan {
            assert!(
                (first..first + 5).contains(&s.slot),
                "slot {} outside submission window",
                s.slot
            );
            assert_eq!(s.target_epoch, 42);
            if s.ticket.proxy == nut_index {
                assert_eq!(s.delivery, TicketDelivery::Ce131);
                assert_eq!(s.slot, first);
            } else {
                assert_eq!(s.delivery, TicketDelivery::Ce132);
            }
        }
        let plan2 = plan_tickets(&tickets, nut_index, first, 42);
        assert_eq!(plan, plan2);
        Ok(())
    }

    #[test]
    fn entropy_from_storage_index_1() -> Result<(), ChainError> {
        let chain = RefChain::tiny(1..6)?;
        let ctx = chain.ticket_ctx()?;
        assert_eq!(ctx.entropy.len(), 32);
        let storage = chain.harness().storage(None);
        let entropy = storage
            .entropy()
            .map_err(|e| ChainError::Tickets(e.to_string()))?;
        assert_eq!(ctx.entropy, entropy[1].0);
        Ok(())
    }

    #[test]
    fn delivery_starts_inside_the_current_submission_window() {
        let period = jam_types::epoch_period();
        let now = 100 * period + 2;

        let first = first_delivery_slot(now);

        assert_eq!(
            first,
            now + 1,
            "with the submission window open, delivery starts at the next slot"
        );
        assert!(
            first - now <= period,
            "delivery must not be pushed a whole epoch out"
        );
    }

    #[test]
    fn delivery_defers_to_next_window_inside_the_epoch_tail() {
        let period = jam_types::epoch_period();
        let tail = jam_types::epoch_tail_start();
        let now = 100 * period + tail;

        let first = first_delivery_slot(now);

        assert!(
            first >= 101 * period,
            "inside the tail the submission window is closed, so defer"
        );
        assert!(first <= 101 * period + 1);
    }

    #[test]
    fn planned_delivery_fits_a_short_observation_window() {
        let period = jam_types::epoch_period();
        let now = 100 * period + 1;
        let tickets: Vec<EmulatedTicket> = (0..5)
            .map(|author| EmulatedTicket {
                id: [author as u8; 32],
                author,
                attempt: 0,
                proof: [0u8; 784],
                proxy: 5,
            })
            .collect();

        let plan = plan_tickets(&tickets, 5, first_delivery_slot(now), 101);
        let last = plan
            .iter()
            .map(|scheduled| scheduled.slot)
            .max()
            .expect("plan is non-empty");

        assert!(
            last - now <= 10,
            "every ticket must be delivered within ~60s of the run start, \
             got slot {last} vs now {now}"
        );
    }
}
